preludes.pgU64:
if (!function_exists(__NAMESPACE__.'\\__pg_u64parse')) {
    // a u64 above PHP_INT_MAX has no PHP int: refuse it loudly instead of clamping (SPEC 3.C PHP caveat)
    function __pg_u64parse($s) {
        $d = ltrim(ltrim($s, '+'), '0');
        if (strlen($d) > 19 || (strlen($d) === 19 && strcmp($d, '9223372036854775807') > 0)) {
            throw new \Error("u64.parse: '" . $s . "' exceeds PHP's 63-bit integer range");
        }
        return intval($s);
    }
}

preludes.pgU16:
if (!function_exists(__NAMESPACE__.'\\__pg_u16')) {
    // UTF-16 code-unit indexing over PHP's UTF-8 strings (P40 B3, D15: needs ext-iconv). An ASCII string is
    // its own UTF-16 index space (fast path); any other is indexed through a cached UTF-16LE copy.
    function __pg_u16($s) {
        // null when ASCII, else the UTF-16LE copy. A short string is just recomputed; a long one is cached
        // (the last one, plus a small LRU), so indexing a long string in a loop is O(1) per call.
        static $ks = null, $kv = null, $lru = [];
        if ($ks === $s) {
            return $kv;
        }
        if (strlen($s) < 256) {
            return preg_match('/[\x80-\xFF]/', $s) ? __pg_u16le($s) : null;
        }
        if (array_key_exists($s, $lru)) {
            $v = $lru[$s];
            unset($lru[$s]);
        } else {
            $v = preg_match('/[\x80-\xFF]/', $s) ? __pg_u16le($s) : null;
            if (count($lru) >= 8) {
                unset($lru[array_key_first($lru)]);
            }
        }
        $lru[$s] = $v;
        $ks = $s;
        $kv = $v;
        return $v;
    }
    function __pg_u16le($s) {
        if (!function_exists('iconv')) {
            throw new \Error('Polyglot: the PHP target needs the iconv extension (ext-iconv) for non-ASCII strings');
        }
        $r = @iconv('UTF-8', 'UTF-16LE', $s);
        if ($r !== false) {
            return $r;
        }
        // not valid UTF-8: a lone surrogate a substring split off (held as WTF-8) — decode by hand
        $out = '';
        $n = strlen($s);
        for ($i = 0; $i < $n;) {
            $b = ord($s[$i]);
            if ($b < 0x80) {
                $c = $b;
                $i += 1;
            } elseif ($b < 0xE0) {
                $c = (($b & 0x1F) << 6) | (ord($s[$i + 1]) & 0x3F);
                $i += 2;
            } elseif ($b < 0xF0) {
                $c = (($b & 0x0F) << 12) | ((ord($s[$i + 1]) & 0x3F) << 6) | (ord($s[$i + 2]) & 0x3F);
                $i += 3;
            } else {
                $c = (($b & 0x07) << 18) | ((ord($s[$i + 1]) & 0x3F) << 12) | ((ord($s[$i + 2]) & 0x3F) << 6) | (ord($s[$i + 3]) & 0x3F);
                $i += 4;
            }
            if ($c >= 0x10000) {
                $c -= 0x10000;
                $out .= pack('v2', 0xD800 + ($c >> 10), 0xDC00 + ($c & 0x3FF));
            } else {
                $out .= pack('v', $c);
            }
        }
        return $out;
    }
    function __pg_u16_unit8($c) {
        if ($c < 0x80) {
            return chr($c);
        }
        if ($c < 0x800) {
            return chr(0xC0 | ($c >> 6)) . chr(0x80 | ($c & 0x3F));
        }
        return chr(0xE0 | ($c >> 12)) . chr(0x80 | (($c >> 6) & 0x3F)) . chr(0x80 | ($c & 0x3F));
    }
    function __pg_u16_to8($u) {
        $r = @iconv('UTF-16LE', 'UTF-8', $u);
        if ($r !== false) {
            return $r;
        }
        $out = '';
        $n = strlen($u);
        for ($i = 0; $i < $n; $i += 2) {
            $c = ord($u[$i]) | (ord($u[$i + 1]) << 8);
            if ($c >= 0xD800 && $c <= 0xDBFF && $i + 3 < $n) {
                $d = ord($u[$i + 2]) | (ord($u[$i + 3]) << 8);
                if ($d >= 0xDC00 && $d <= 0xDFFF) {
                    $c = 0x10000 + (($c - 0xD800) << 10) + ($d - 0xDC00);
                    $out .= chr(0xF0 | ($c >> 18)) . chr(0x80 | (($c >> 12) & 0x3F)) . chr(0x80 | (($c >> 6) & 0x3F)) . chr(0x80 | ($c & 0x3F));
                    $i += 2;
                    continue;
                }
            }
            $out .= __pg_u16_unit8($c);
        }
        return $out;
    }
    function __pg_len16($s) {
        $v = __pg_u16($s);
        return $v === null ? strlen($s) : strlen($v) >> 1;
    }
    function __pg_u16_char($s, $i) {
        $v = __pg_u16($s);
        return $v === null ? $s[$i] : __pg_u16_unit8(ord($v[2 * $i]) | (ord($v[2 * $i + 1]) << 8));
    }
    function __pg_u16_cp($s, $i) {
        $v = __pg_u16($s);
        if ($v === null) {
            return ord($s[$i]);
        }
        $c = ord($v[2 * $i]) | (ord($v[2 * $i + 1]) << 8);
        if ($c >= 0xD800 && $c <= 0xDBFF && 2 * $i + 3 < strlen($v)) {
            $d = ord($v[2 * $i + 2]) | (ord($v[2 * $i + 3]) << 8);
            if ($d >= 0xDC00 && $d <= 0xDFFF) {
                return 0x10000 + (($c - 0xD800) << 10) + ($d - 0xDC00);
            }
        }
        return $c;
    }
    function __pg_u16_sub($s, $a, $b) {
        $v = __pg_u16($s);
        return $v === null ? substr($s, $a, $b - $a) : __pg_u16_to8(substr($v, 2 * $a, 2 * ($b - $a)));
    }
    function __pg_u16_find($s, $n, $f) {
        static $kn = null, $kascii = true, $kv = '';
        if ($kn !== $n) {
            $kascii = !preg_match('/[\x80-\xFF]/', $n);
            $kv = null;
            $kn = $n;
        }
        $v = __pg_u16($s);
        if ($v === null) {
            if (!$kascii) {
                return -1;
            }
            $p = strpos($s, $n, $f);
            return $p === false ? -1 : $p;
        }
        if ($kv === null) {
            $kv = __pg_u16le($n); // the needle is reconverted only when it changes
        }
        $p = 2 * $f;
        while (($p = strpos($v, $kv, $p)) !== false) {
            if (($p & 1) === 0) {
                return $p >> 1;
            }
            $p++;
        }
        return -1;
    }
    function __pg_cmp16($a, $b) {
        if (preg_match('/[\x80-\xFF]/', $a) || preg_match('/[\x80-\xFF]/', $b)) {
            // UTF-16BE bytes order exactly as UTF-16 code units do (UTF-8 bytes order as code points)
            $a = $a === '' ? '' : pack('n*', ...unpack('v*', __pg_u16le($a)));
            $b = $b === '' ? '' : pack('n*', ...unpack('v*', __pg_u16le($b)));
        }
        $r = strcmp($a, $b);
        return $r < 0 ? -1 : ($r > 0 ? 1 : 0);
    }
    function __pg_u16_lone(...$xs) {
        // a lone surrogate (held as WTF-8, ED A0-BF ..) only matches like C#/TS in the UTF-16 view; without
        // one, the UTF-8 byte answer is the UTF-16 answer
        foreach ($xs as $x) {
            if (preg_match('/\xED[\xA0-\xBF]/', $x)) {
                return true;
            }
        }
        return false;
    }
    function __pg_u16_has($s, $n) {
        return __pg_u16_lone($s, $n) ? __pg_u16_find($s, $n, 0) !== -1 : str_contains($s, $n);
    }
    function __pg_u16_starts($s, $p) {
        return __pg_u16_lone($s, $p) ? str_starts_with(__pg_u16le($s), __pg_u16le($p)) : str_starts_with($s, $p);
    }
    function __pg_u16_ends($s, $p) {
        return __pg_u16_lone($s, $p) ? str_ends_with(__pg_u16le($s), __pg_u16le($p)) : str_ends_with($s, $p);
    }
    function __pg_u16_pieces($s, $sep) {
        // the UTF-16LE pieces of $s around $sep, matching only at unit-aligned (even) offsets
        $v = __pg_u16le($s);
        $k = __pg_u16le($sep);
        $kl = strlen($k);
        $out = [];
        $from = 0;
        $p = 0;
        while (($p = strpos($v, $k, $p)) !== false) {
            if (($p & 1) === 0) {
                $out[] = substr($v, $from, $p - $from);
                $p += $kl;
                $from = $p;
            } else {
                $p++;
            }
        }
        $out[] = substr($v, $from);
        return $out;
    }
    function __pg_u16_replace($s, $n, $r) {
        if (!__pg_u16_lone($s, $n, $r)) {
            return str_replace($n, $r, $s);
        }
        return __pg_u16_to8(implode(__pg_u16le($r), __pg_u16_pieces($s, $n)));
    }
    function __pg_u16_split($s, $sep) {
        if (!__pg_u16_lone($s, $sep)) {
            return explode($sep, $s);
        }
        return array_map(fn($u) => __pg_u16_to8($u),__pg_u16_pieces($s, $sep));
    }
}

preludes.pgChr8:
if (!function_exists(__NAMESPACE__.'\\__pg_chr8')) {
    // a Unicode scalar value -> UTF-8 (string.fromCodePoint; no mbstring needed, S17)
    function __pg_chr8($c) {
        if ($c < 0x80) {
            return chr($c);
        }
        if ($c < 0x800) {
            return chr(0xC0 | ($c >> 6)) . chr(0x80 | ($c & 0x3F));
        }
        if ($c < 0x10000) {
            return chr(0xE0 | ($c >> 12)) . chr(0x80 | (($c >> 6) & 0x3F)) . chr(0x80 | ($c & 0x3F));
        }
        return chr(0xF0 | ($c >> 18)) . chr(0x80 | (($c >> 12) & 0x3F)) . chr(0x80 | (($c >> 6) & 0x3F)) . chr(0x80 | ($c & 0x3F));
    }
}

preludes.pgMap:
if (!function_exists(__NAMESPACE__.'\\__pg_mk')) {
    // Map<K, V> over \ArrayObject (P40 B4). A PHP array turns the string key "10" into the int 10, so string
    // keys are stored prefixed with "s" and stripped again by keys(); integer keys are stored as they are.
    function __pg_mk($k) {
        return is_int($k) ? $k : "s" . $k;
    }
    function __pg_mget($m, $k) {
        $k = __pg_mk($k);
        return $m->offsetExists($k) ? $m[$k] : null;
    }
    function __pg_mdel($m, $k) {
        $k = __pg_mk($k);
        if (!$m->offsetExists($k)) {
            return false;
        }
        $m->offsetUnset($k);
        return true;
    }
    function __pg_mkeys($m) {
        $r = [];
        foreach ($m as $k => $v) {
            $r[] = is_int($k) ? $k : substr($k, 1);
        }
        return new \ArrayObject($r);
    }
}

preludes.pgNn:
if (!function_exists(__NAMESPACE__.'\\__pg_nn')) {
    function __pg_nn($v, $at) {
        if ($v === null) {
            throw new \UnexpectedValueException("null-assert failed (" . $at . ")");
        }
        return $v;
    }
}

preludes.pgStr:
if (!function_exists(__NAMESPACE__.'\\__pg_str')) {
    function __pg_str($x) {
        if ($x === null) {
            return "null";
        }
        if (is_bool($x)) {
            return $x ? "true" : "false";
        }
        if (is_string($x)) {
            if (preg_match('//u', $x)) {
                return $x;
            }
            $x = preg_replace_callback('/\xED([\xA0-\xAF])([\x80-\xBF])\xED([\xB0-\xBF])([\x80-\xBF])/', function ($m) {
                $c = 0x10000 + ((((ord($m[1]) & 0x0F) << 6) | (ord($m[2]) & 0x3F)) << 10) + ((((ord($m[3]) & 0x0F) << 6) | (ord($m[4]) & 0x3F)));
                return chr(0xF0 | ($c >> 18)) . chr(0x80 | (($c >> 12) & 0x3F)) . chr(0x80 | (($c >> 6) & 0x3F)) . chr(0x80 | ($c & 0x3F));
            }, $x);
            return preg_replace('/\xED[\xA0-\xBF][\x80-\xBF]/', "\u{FFFD}", $x);
        }
        if (!is_float($x)) {
            return (string)$x;
        }
        if (is_nan($x)) {
            return "NaN";
        }
        if (is_infinite($x)) {
            return $x > 0 ? "Infinity" : "-Infinity";
        }
        if ($x == 0.0) {
            return "0";
        }
        $old = ini_set('serialize_precision', '-1');
        $s = var_export($x, true);
        if ($old !== false) {
            ini_set('serialize_precision', $old);
        }
        $neg = $s[0] === '-';
        if ($neg) {
            $s = substr($s, 1);
        }
        $p = strpos($s, 'E');
        $m = $p === false ? $s : substr($s, 0, $p);
        $e = $p === false ? 0 : (int)substr($s, $p + 1);
        $dot = strpos($m, '.');
        $i = $dot === false ? $m : substr($m, 0, $dot);
        $f = $dot === false ? '' : substr($m, $dot + 1);
        $d = ltrim($i . $f, '0');
        $n = strlen($i) + $e - (strlen($i) + strlen($f) - strlen($d));
        $d = rtrim($d, '0');
        $k = strlen($d);
        if ($k <= $n && $n <= 21) {
            $r = $d . str_repeat('0', $n - $k);
        } elseif (0 < $n && $n <= 21) {
            $r = substr($d, 0, $n) . '.' . substr($d, $n);
        } elseif (-6 < $n && $n <= 0) {
            $r = '0.' . str_repeat('0', -$n) . $d;
        } else {
            $r = $d[0] . ($k > 1 ? '.' . substr($d, 1) : '') . 'e' . ($n >= 1 ? '+' : '-') . abs($n - 1);
        }
        return $neg ? '-' . $r : $r;
    }
}
